@Component("employee-handler")
@ProcessingGroup("employee-processing-group")
public class EmployeeEventHandler {
	
	// core constructor
	EmployeeEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateEmployeeEvent
     */
    @EventHandler
    public void handle( CreateEmployeeEvent event) {
        entityManager.persist(new Employee(event.getEmployeeId(), event.getFirstName(), event.getLastName(), event.getWorkCenter(), event.getShiftAssignments(), event.getCorrectiveActions(), event.getRole(), event.getSkillLevel()));
    }

    /*
     * @param	event UpdateEmployeeEvent
     */
    @EventHandler
    public Employee handle( UpdateEmployeeEvent event) {
    	entityManager.merge(new Employee(event.getEmployeeId(), event.getFirstName(), event.getLastName(), event.getWorkCenter(), event.getShiftAssignments(), event.getCorrectiveActions(), event.getRole(), event.getSkillLevel()));
    }
    
    /*
     * @param	event DeleteEmployeeEvent
     */
    @EventHandler
    public void on( DeleteEmployeeEvent event) {
    	Employee entity = new Employee();
   
    	// ------------------------------------------
    	// apply the EmployeeId
    	// ------------------------------------------
    	entity.setEmployeeId( event.getEmployeeId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final EmployeeRepository employeeEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(EmployeeEventHandler.class.getName());

}
